/* N2 shares the existing study archive, audio, favorites and cloud document. */
const n2Unit=id=>N2_UNITS.find(u=>u.id===id);
const n2State=u=>state.n2.units[u.id]??={done:[],ratings:[],answers:{},review:{},draft:''};
const n2Next=()=>N2_UNITS.find(u=>!n2State(u).done.includes('review'));
const n2Ids=u=>[...u.grammarIds,...u.reading.ids,...u.listening.ids];
const n2FinalIds=()=>N2_UNITS.flatMap((u,i)=>[u.grammarIds[i%2],u[i%2?'reading':'listening'].ids[0]]);
const n2Pct=()=>Math.round(N2_UNITS.reduce((n,u)=>n+n2State(u).done.length,0)/120*100);
const n2Score=(ids,map)=>Math.round(ids.filter(id=>map[id]===questionById(id).answer).length/ids.length*100);
let n2FinalOpen=false,n2Guided=false;
function n2CanFinish(u,k){const s=n2State(u);if(k==='words')return u.wordIds.every(id=>s.ratings.includes(id));const ids=k==='grammar'?u.grammarIds:k==='review'?n2Ids(u):u[k].ids,map=k==='review'?s.review:s.answers;return ids.every(id=>Number.isInteger(map[id]))&&(k!=='review'||N2_STAGES.slice(0,4).every(k=>s.done.includes(k))&&n2Score(ids,map)>=80);}
function n2Paint(){const open=[...document.querySelectorAll('[data-n2detail][open]')].map(x=>x.dataset.n2detail),top=window.scrollY;render(false);for(const el of document.querySelectorAll('[data-n2detail]'))if(open.includes(el.dataset.n2detail))el.open=true;window.scrollTo({top,behavior:'instant'});}
function n2Question(id,map,kind){const q=questionById(id),a=map[id],answered=Number.isInteger(a),final=kind==='final';return `<article class="n5-question" id="n2q-${id}"><h3>${esc(q.q)}</h3><div class="answers">${q.options.map((o,i)=>`<button data-n2answer="${id}" data-kind="${kind}" data-value="${i}" ${answered&&!final?'disabled':''} ${final?`aria-pressed="${a===i}"`:''} class="${final?(a===i?'selected':''):answered&&i===q.answer?'correct':answered&&a===i?'wrong':''}">${esc(o)}</button>`).join('')}</div>${answered&&!final?`<p class="feedback" role="status">${a===q.answer?'✓ 正确':'✕ 再理解一次'} · ${esc(q.why)}</p>`:''}</article>`;}
function n2Text(u,kind,map,mode='answers'){const t=u[kind],audio=kind==='listening';return `<article class="n5-text"><h2>${esc(u.title)} · ${N2_STAGE_LABELS[kind]}</h2>${audio?`<button class="primary" data-speak="${esc(t.text)}">▷ 播放对话</button><button class="secondary" data-stop-audio="true">停止</button><details data-n2detail="${u.id}-${kind}-text"><summary>听后查看原文</summary><p class="japanese-text" lang="ja">${esc(t.text)}</p></details>`:`<p class="japanese-text" lang="ja">${esc(t.text)}</p>`}<details data-n2detail="${u.id}-${kind}-translation"><summary>中文对照</summary><p>${esc(t.translation)}</p></details>${t.ids.map(id=>n2Question(id,map,mode)).join('')}</article>`;}
function n2Daily(){if(state.n2.day)return state.n2.day;const u=n2Next();if(!u)return null;const stages=N2_STAGES.filter(k=>!n2State(u).done.includes(k)).slice(0,state.plan.minutes===20?1:state.plan.minutes===60?3:2);state.n2.day={unit:u.id,stages};persist();return state.n2.day;}
function n2DailyHtml(home=false){const d=n2Daily();if(!d)return `<section class="container page-section"><h2>24 个 N2 单元已通过</h2><button class="primary" id="n2Final">进行结课测评 →</button><button class="secondary" data-page="favorites">复习收藏</button></section>`;const u=n2Unit(d.unit),s=n2State(u),all=d.stages.every(k=>s.done.includes(k)),active=d.stages.find(k=>!s.done.includes(k));return `<section class="container page-section"><div class="dash-section-head"><h2>今日 N2 学习</h2><span>第 ${state.n2.number} 学习日 · ${state.plan.minutes} 分钟</span></div><h3>第 ${N2_UNITS.indexOf(u)+1} 单元 · ${esc(u.title)}</h3><div class="dash-task-list">${d.stages.map((k,i)=>`<button class="dash-task ${s.done.includes(k)?'is-done':k===active?'is-current':'is-pending'}" data-n2daily="${k}" ${!all&&k!==active&&!s.done.includes(k)?'disabled':''}><span class="dash-task-number">${s.done.includes(k)?'✓':i+1}</span><strong>${N2_STAGE_LABELS[k]}</strong></button>`).join('')}</div><div class="toolbar">${all?'<button class="primary" id="n2NextDay">开始下一学习日 →</button>':''}${!home?'<button class="secondary" id="n2Budget">调整每日时间</button><button class="secondary" id="n2Overview">全部 N2 课程</button>':''}</div></section>`;}
function n2Overview(){const next=n2Next();return title('','N2 系统课程','')+`<section class="container page-section"><div class="n5-course-hero"><div><h2>读懂观点、逻辑与言外之意</h2><p>24 单元 · 48 节句型 · 288 条单元词汇 · 48 篇读听材料</p><div class="toolbar">${next?`<button class="primary" data-n2unit="${next.id}">继续第 ${N2_UNITS.indexOf(next)+1} 单元 →</button>`:''}<button class="secondary" id="n2UsePlan">加入每日计划</button><button class="secondary" id="n2Final">结课测评</button></div></div><div><b>${n2Pct()}%</b><p>${N2_UNITS.filter(u=>n2State(u).done.includes('review')).length}/24 单元通过</p></div></div><details class="learning-help"><summary>课程范围与学习方式</summary><p>原创 N2 教学选编，接续 N3，练习正式表达、让步对比、判断义务、范围与论证，部分句型同时作进阶复习。每节含接续、易错点、两组例句；每篇阅读与听力各四题，使用日文题干和四选一选项。单元词汇含跨单元复现，并非 288 个全新词或官方完整考纲。听力使用合成语音，建议搭配官方真人材料。完成前四步、单元复习至少答对 8/10 题后通过。</p><a href="https://www.jlpt.jp/e/about/levelsummary.html" target="_blank" rel="noopener">JLPT 官方能力说明 ↗</a></details>${N2_MODULES.map((name,m)=>`<div class="sectionhead"><h2>${m+1}. ${esc(name)}</h2><button class="secondary" data-n2focus="${m}">本模块专项练习 →</button></div><div class="n5-unit-grid">${N2_UNITS.filter(u=>u.module===m).map(u=>{const s=n2State(u),started=s.done.length||s.ratings.length||Object.keys(s.answers).length,passed=s.done.includes('review');return `<button class="n5-unit-card ${passed?'n2-passed':started?'n2-started':''}" data-n2unit="${u.id}"><span class="label">第 ${N2_UNITS.indexOf(u)+1} 单元</span><span class="n5-badge">${passed?'✓ 已通过':started?'◐ 学习中':'○ 未开始'}</span><h3>${esc(u.title)}</h3><div class="bar"><div style="width:${s.done.length/5*100}%"></div></div><span>${s.done.length}/5 步骤 · ${u.grammar.map(g=>esc(g.title)).join(' / ')}</span></button>`;}).join('')}</div>`).join('')}</section>`;}
function n2UnitHtml(u){const s=n2State(u),k=state.n2.stage;let body='';
 if(k==='words')body=`<div class="n5-word-grid">${u.wordIds.map(id=>{const w=words.find(w=>w.id===id);return `<article class="n5-word" data-word-id="${id}"><span class="n5-badge">${s.ratings.includes(id)?'✓ 已自评':'○ 待认读'}</span><h3 lang="ja">${esc(w.word)}</h3>${n4Favorite('word:'+id)}<details data-expand-reading="${esc(w.reading)}"><summary>展开读音与词义</summary><p lang="ja">${esc(w.reading)}</p>${romanLine(w.reading)}<p class="vocab-meaning"><span>词义</span> <strong>${esc(w.meaning)}</strong></p><p><span>词性</span> <span class="pos-badge">${esc(w.pos)}</span></p><button class="secondary" data-speak="${esc(w.reading)}">▷ 听读音</button><div class="toolbar"><button class="secondary" data-n2rate="${id}" data-value="0">还不熟</button><button class="primary" data-n2rate="${id}" data-value="1">记住了 ✓</button></div></details></article>`;}).join('')}</div>`;
 if(k==='grammar')body=u.grammar.map(g=>`<article class="n5-grammar"><h2>${esc(g.title)}</h2>${n4Favorite('grammar:'+g.id)}<p>${esc(g.rule)}</p>${g.examples.map(([ja,kana,zh],i)=>`<div class="example"><b lang="ja">${esc(ja)}</b><p lang="ja">${esc(kana)}</p>${romanLine(kana,true)}<p>${esc(zh)}</p><button class="secondary" data-speak="${esc(ja)}">▷ 跟读</button>${n4Favorite('example:'+g.id+':'+i)}</div>`).join('')}<div class="hint">易错点：${esc(g.pitfall)}</div>${n2Question(g.id,s.answers,'answers')}</article>`).join('');
 if(k==='reading'||k==='listening')body=n2Text(u,k,s.answers);
 if(k==='review')body='<p>10 题 · 至少答对 8 题，并完成前四步后通过。</p>'+u.grammarIds.map(id=>n2Question(id,s.review,'review')).join('')+n2Text(u,'reading',s.review,'review')+n2Text(u,'listening',s.review,'review');
 return title('','N2 · '+u.title,'')+`<section class="container page-section"><div class="toolbar"><button class="secondary" id="n2Overview">← 全部单元</button><button data-page="plan" data-level="N2" class="secondary">每日计划</button><span>第 ${N2_UNITS.indexOf(u)+1}/24 单元</span></div><div class="n5-stage-tabs" role="group" aria-label="单元步骤">${N2_STAGES.map((st,i)=>`<button data-n2stage="${st}" aria-pressed="${st===k}" class="${st===k?'selected':''}">${s.done.includes(st)?'✓':i+1} ${N2_STAGE_LABELS[st]}</button>`).join('')}</div>${body}<div class="n5-finish"><p id="n2FinishStatus" role="status">${s.done.includes(k)?'✓ 本步已完成':n2CanFinish(u,k)?'可以完成本步了':k==='review'?'先完成前四步，并达到 80%':'完成本步全部自评或作答后继续'}</p><button class="primary" id="n2Finish" ${!n2CanFinish(u,k)?'disabled':''}>${k==='review'?'通过单元，继续 →':'完成本步，继续 →'}</button>${k!=='words'?'<button class="secondary" id="n2Retry">重做本步练习</button>':''}</div><details class="writing-panel" data-n2detail="${u.id}-writing"><summary>可选写作 · 用两个句型写一段话</summary><textarea id="n2Draft" maxlength="4000" aria-label="单元写作草稿">${esc(s.draft)}</textarea><p id="n2DraftStatus" role="status">草稿自动保存</p><details><summary>写作提示与参考</summary><p>用「${esc(u.grammar[0].title)}」和「${esc(u.grammar[1].title)}」围绕本课话题提出观点，补充理由、反例或适用条件。</p>${u.grammar.map(g=>`<p lang="ja">${esc(g.examples[1][0])}</p><p>${esc(g.examples[1][2])}</p>`).join('')}<p>检查接续、前后逻辑、时态与助词；参考句不代表唯一答案。</p></details></details></section>`;
}
function n2FinalHtml(){const f=state.n2.final,ids=n2FinalIds(),answered=ids.filter(id=>Number.isInteger(f.answers[id])).length;return title('','N2 结课测评','')+`<section class="container page-section"><button class="secondary" id="n2Overview">← 全部单元</button><p>48 题 · 已答 ${answered}/48 · 可离开后继续作答</p>${f.submitted?`<h2>正确率 ${n2Score(ids,f.answers)}%</h2><button class="secondary" id="n2ResetFinal">开始新一轮测评</button>`:'<p>交卷后统一显示答案与解析；交卷前可以修改选择。</p>'}${ids.map((id,i)=>{const q=questionById(id);return `<section class="n2-exam-item"><span class="label">${i+1}/48 · ${typeNames[q.type]}</span>${q.text?(q.type==='listening'?`<button class="secondary" data-speak="${esc(q.text)}">▷ 播放听力</button><button class="secondary" data-stop-audio="true">停止</button>${f.submitted?`<p class="japanese-text" lang="ja">${esc(q.text)}</p>`:''}`:`<p class="japanese-text" lang="ja">${esc(q.text)}</p>`):''}${f.submitted?`<h3>${esc(q.q)}</h3><p>${f.answers[id]===q.answer?'✓ 正确':'✕ 答错'} · 你的选择：${esc(q.options[f.answers[id]])}</p><div class="hint">答案：${esc(q.options[q.answer])}<p>${esc(q.why)}</p></div>`:n2Question(id,f.answers,'final')}</section>`;}).join('')}${!f.submitted?`<button class="primary" id="n2SubmitFinal" ${answered<ids.length?'disabled':''}>交卷并查看解析</button>`:''}</section>`;}
const n2PreviousLessons=renderLessons;renderLessons=function(isGrammar=false){return level==='N2'&&!isGrammar?n2FinalOpen?n2FinalHtml():state.n2.cursor?n2UnitHtml(n2Unit(state.n2.cursor)):n2Overview():n2PreviousLessons(isGrammar);};
const n2PreviousPlan=renderPlan;renderPlan=function(){return level==='N2'?title('','N2 每日计划','')+n2DailyHtml():n2PreviousPlan();};
const n2PreviousProgress=dashboardProgress;dashboardProgress=function(l){return l==='N2'?n2Pct():n2PreviousProgress(l);};
const n2PreviousHome=renderHome;renderHome=function(){let html=n2PreviousHome().replace('N2</strong><span>核心练习','N2</strong><span>系统课程');if(level==='N2'){const u=n2Unit(state.n2.cursor)||n2Next()||N2_UNITS.at(-1);if(!state.activeQuiz)html=html.replace(esc(nextGrammar('N2').title),esc(u.title)).replace(`data-lesson="${nextGrammar('N2').id}"`,`data-n2unit="${u.id}"`).replace('核心练习进度','单元步骤进度');html=html.replace(/<section class="container dash-today">[\s\S]*?<\/section>/,n2DailyHtml(true));}return html;};
const n2PreviousTexts=renderTexts;renderTexts=function(kind){if(level!=='N2')return n2PreviousTexts(kind);return title('',kind==='reading'?'N2 阅读训练':'N2 听力训练','')+`<section class="container page-section"><p>24 个主题 · 每篇 4 题</p><div class="n5-unit-grid">${N2_UNITS.map((u,i)=>`<button class="n5-unit-card" data-n2unit="${u.id}" data-n2open="${kind}"><span class="label">第 ${i+1} 单元</span><span class="n5-badge">${n2State(u).done.includes(kind)?'✓ 已完成':'○ 待学习'}</span><h3>${esc(u.title)}</h3><span>打开课文与练习 →</span></button>`).join('')}</div><details class="learning-help"><summary>原有核心训练篇章</summary>${(kind==='reading'?readings:listenings).filter(q=>q.level==='N2'&&!q.unit).map(q=>`<article class="text-card"><h3>${esc(q.title)}</h3>${kind==='listening'?`<button class="secondary" data-speak="${esc(q.text)}">▷ 播放</button>`:''}<p class="japanese-text">${esc(q.text)}</p>${answerBlock(q)}<button class="secondary" data-textdone="${q.id}" disabled>完成并记录</button></article>`).join('')}</details></section>`;};
const n2PreviousArchive=renderProgress;renderProgress=function(){return n2PreviousArchive()+`<section class="container page-section"><h2>N2 系统课程</h2><p>${N2_UNITS.filter(u=>n2State(u).done.includes('review')).length}/24 单元通过 · ${n2Pct()}% 步骤完成${state.n2.final.submitted?' · 结课 '+n2Score(n2FinalIds(),state.n2.final.answers)+'%':''}</p><button class="primary" data-n2unit="${(n2Next()||N2_UNITS.at(-1)).id}">继续 N2 →</button></section>`;};
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;
 if(d.n2unit){const u=n2Unit(d.n2unit);if(!u)return;state.n2.cursor=u.id;state.n2.stage=N2_STAGES.includes(d.n2open)?d.n2open:N2_STAGES.find(k=>!n2State(u).done.includes(k))||'review';n2FinalOpen=false;n2Guided=false;persist();go('lessons','N2');render();}
 if(d.n2stage&&N2_STAGES.includes(d.n2stage)){state.n2.stage=d.n2stage;persist();render();}
 if(d.n2daily){const day=n2Daily();if(!day||!day.stages.includes(d.n2daily))return;const s=n2State(n2Unit(day.unit)),active=day.stages.find(k=>!s.done.includes(k));if(active&&d.n2daily!==active&&!s.done.includes(d.n2daily))return;state.n2.cursor=day.unit;state.n2.stage=d.n2daily;n2FinalOpen=false;n2Guided=true;persist();go('lessons','N2');render();}
 if(b.id==='n2Overview'){state.n2.cursor=null;n2FinalOpen=false;n2Guided=false;persist();go('lessons','N2');render();}
 if(b.id==='n2UsePlan'){state.plan.start='N2';if(LEVELS.indexOf(state.plan.target)<LEVELS.indexOf('N2'))state.plan.target='N2';persist();go('plan','N2');render();}
 if(b.id==='n2Budget'){const vals=[20,40,60];state.plan.minutes=vals[(vals.indexOf(state.plan.minutes)+1)%3];persist();n2Paint();toast('每天 '+state.plan.minutes+' 分钟，下个学习日生效。');}
 if(b.id==='n2NextDay'){const day=n2Daily();if(day&&day.stages.every(k=>n2State(n2Unit(day.unit)).done.includes(k))){state.n2.day=null;state.n2.number++;persist();render(false);}}
 if(d.n2answer){const q=questionById(d.n2answer),a=Number(d.value),u=n2Unit(state.n2.cursor),final=d.kind==='final';if(!q||!Number.isInteger(a)||!q.options[a])return;if(final){if(state.n2.final.submitted||!n2FinalIds().includes(q.id))return;}else if(!u||!['answers','review'].includes(d.kind)||!n2Ids(u).includes(q.id))return;const map=final?state.n2.final.answers:n2State(u)[d.kind];if(!final&&map[q.id]!==undefined)return;map[q.id]=a;if(!final)recordAnswer(q,a);persist();n2Paint();}
 if(d.n2rate){const u=n2Unit(state.n2.cursor);if(!u?.wordIds.includes(d.n2rate))return;const s=n2State(u);s.ratings=[...new Set([...s.ratings,d.n2rate])];const old=state.wordReviews[d.n2rate],box=d.value==='1'?old?.last===dateKey()?Math.max(old.box,1):Math.min((old?.box||0)+1,6):0;state.wordReviews[d.n2rate]={box,due:box?afterDays([1,3,7,14,30,60][box-1]):dateKey(),last:dateKey()};touch('vocab');persist();b.textContent=d.value==='1'?'✓ 已记住':'↺ 待巩固';const badge=b.closest?.('[data-word-id]')?.querySelector('.n5-badge');if(badge)badge.textContent='✓ 已自评';$('#n2Finish').disabled=!n2CanFinish(u,'words');$('#n2FinishStatus').textContent=n2CanFinish(u,'words')?'可以完成本步了':'已自评 '+s.ratings.length+'/'+u.wordIds.length+' 个';}
 if(b.id==='n2Finish'){const u=n2Unit(state.n2.cursor),k=state.n2.stage;if(!u||!n2CanFinish(u,k))return;const s=n2State(u);if(!s.done.includes(k)){s.done.push(k);if(k==='grammar')u.grammarIds.forEach(markLesson);if(k==='reading'||k==='listening')state.textDone=[...new Set([...state.textDone,...u[k].ids])];touch(k==='words'?'vocab':k==='review'?'practice':k);}const next=N2_STAGES[N2_STAGES.indexOf(k)+1];if(next)state.n2.stage=next;else state.n2.cursor=null;persist();if(n2Guided)go('plan','N2');render();toast(k==='review'?'✓ 单元通过，记录已保存。':'本步已保存。');}
 if(b.id==='n2Retry'){const u=n2Unit(state.n2.cursor),k=state.n2.stage;if(!u||k==='words')return;for(const id of k==='grammar'?u.grammarIds:k==='review'?n2Ids(u):u[k].ids)delete(k==='review'?n2State(u).review:n2State(u).answers)[id];persist();render(false);}
 if(d.n2focus!==undefined){if(state.activeQuiz){go('practice',state.activeQuiz.level);toast('先完成或结束当前练习。');return;}const m=Number(d.n2focus);if(!Number.isInteger(m)||m<0||m>3)return;const ids=N2_UNITS.filter(u=>u.module===m).flatMap((u,i)=>[u.grammarIds[i%2],u[i%2?'reading':'listening'].ids[1]]);guideActive=false;state.activeQuiz={level:'N2',mode:'exam',ids:shuffled(ids),answers:[],index:0};persist();go('practice','N2');render();}
 if(b.id==='n2Final'){n2FinalOpen=true;n2Guided=false;go('lessons','N2');render();}
 if(b.id==='n2SubmitFinal'){const f=state.n2.final;if(f.submitted||!n2FinalIds().every(id=>Number.isInteger(f.answers[id])))return;f.submitted=true;const sections=Object.fromEntries(['grammar','vocab','reading','listening'].map(k=>[k,{correct:0,total:0}]));for(const id of n2FinalIds()){const q=questionById(id);sections[q.type].total++;if(recordAnswer(q,f.answers[id]))sections[q.type].correct++;}state.history.push({date:dateKey(),level:'N2',score:n2Score(n2FinalIds(),f.answers),total:48,sections});state.history=state.history.slice(-100);persist();render();}
 if(b.id==='n2ResetFinal'){state.n2.final={answers:{},submitted:false};persist();render();}
});
document.addEventListener('input',e=>{if(e.target.id==='n2Draft'){const u=n2Unit(state.n2.cursor);if(!u)return;n2State(u).draft=e.target.value.slice(0,4000);persist();$('#n2DraftStatus').textContent='✓ 草稿已保存';}});
render(false);
